      function glyphSvg(name) {
        const s = document.createElementNS("http://www.w3.org/2000/svg", "svg");
        s.setAttribute("viewBox", "0 0 24 24");
        s.setAttribute("aria-hidden", "true");
        s.innerHTML = GLYPH[name];
        return s;
      }

      function renderNode(item, tag = "button") {
        const spec = ICONS[item.name] || {};
        const node = $(tag, "node");
        if (tag === "button") node.type = "button";
        if (spec.c) node.style.setProperty("--c", spec.c);
        node.title = tip(item);
        node.setAttribute(
          "aria-label",
          tip(item) + (tag === "button" ? ", show details" : ""),
        );
        if (tag !== "button") node.setAttribute("role", "img");

        const fallback = () => {
          node.replaceChildren();
          if (spec.glyph) node.appendChild(glyphSvg(spec.glyph));
          else node.appendChild($("span", "abbr", item.abbr));
        };

        if (spec.srcs && spec.srcs.length) {
          const img = new Image();
          img.alt = "";
          img.loading = "lazy";
          img.decoding = "async";
          let i = 0;
          img.onerror = () => {
            i++;
            if (i < spec.srcs.length) img.src = spec.srcs[i];
            else fallback();
          };
          img.src = spec.srcs[0];
          node.appendChild(img);
        } else {
          fallback();
        }
        return node;
      }

      /* ───────────────────────── Hover slowdown ─────────────────────────
   Hovering (or focusing) an icon eases its whole ring down to 5% speed; leaving eases it back to 100%.
   Uses each CSS animation's playbackRate, so the icon never jumps or stops.                          */
      const SLOW = 0.05,
        EASE = 0.14;
      const easing = new Set();
      let raf = 0;
      /* A ring runs slow while it is hovered/focused OR pinned by an open popover. */
      function applyRate(r) {
        const target = r.hover || r.pinned ? SLOW : 1;
        r.wraps.forEach((w) => {
          w._t = target;
          easing.add(w);
        });
        if (!raf) raf = requestAnimationFrame(tick);
      }
      function tick() {
        raf = 0;
        easing.forEach((w) => {
          const a = w._a || (w._a = w.getAnimations()[0]);
          if (!a) {
            easing.delete(w);
            return;
          } // e.g. reduced-motion: nothing animates
          const next = a.playbackRate + (w._t - a.playbackRate) * EASE;
          if (Math.abs(next - w._t) < 0.002) {
            a.playbackRate = w._t;
            easing.delete(w);
          } else a.playbackRate = next;
        });
        if (easing.size) raf = requestAnimationFrame(tick);
      }

